{"charges": [{"claim": "The regex change reduces the maximum allowed length of the hostname part after the first dot from 63 to 62, causing valid hostnames with a 63‑character suffix to not have www. stripped when stripWWW is true.", "file": "index.js", "line": 208, "severity": "major", "witnessCode": "import test from 'node:test';
import assert from 'node:assert/strict';
import normalizeUrl from '../index.js';

test('stripWWW should remove www. when suffix length 63', async t => {
  const input = 'http://www.example.' + 'a'.repeat(63);
  const expected = 'http://example.' + 'a'.repeat(63);
  const actual = normalizeUrl(input, { stripWWW: true });
  assert.strictEqual(actual, expected);
});"}]}
